        "transcript": "SPEAKER: Good morning teachers and parent chaperones, and welcome to Paulton Children's Farm. We host hundreds of primary schools every year, and we want to ensure your day runs smoothly and safely.\nFirst, regarding lunches: each child must bring their own packed lunch in a labelled bag. We ask that teachers collect all lunchboxes upon arrival and place them in the communal lockers in the welcome foyer so children are not carrying bags around the pastures.\nRegarding our farm shop: while children are welcome to browse with an adult, they are only permitted to purchase honey and fruit juice produced on our own estate; sweets and fizzy sodas are strictly prohibited on site.\nHealth and safety is paramount when interacting with livestock. The golden rule is that everyone must wash their hands thoroughly with warm water and antibacterial soap both before eating and immediately after touching any animal or enclosure fence. We have installed sinks along every central walkway.\nIn case of sudden rainy weather, do not worry about getting soaked outdoors. Our indoor discovery barn is fully heated and equipped with interactive educational displays and live chick-hatching incubators.\nNow, let me orient you using the farm map. Directly to the north of the main entrance gate, marked on your plan, you will see the Old Stables at Location D. If you follow the willow-lined path eastward, you will arrive at the Duck Pond at Location B. South of the pond is our heritage Apple Orchard, indicated at Location F. Tucked safely in the peaceful wildflower meadow in the far southeast corner are the Beehives, positioned at Location A. The children will be eager to play; our newly renovated Adventure Playground is right next to the gift shop at Location E. Finally, the covered Picnic Shelter for eating lunch is situated at Location C, beside the herb garden. Have a wonderful day exploring!",
