        "part": 4,
        "title": "The Acoustic Evolution and History of the Guitar",
        "instructions": "Complete the notes below. Write NO MORE THAN TWO WORDS for each answer.",
        "transcript": "LECTURER: Good morning, everyone. In today's lecture on musical acoustics and instrument design, we will examine the historical evolution of the guitar.\nThe origins of stringed chordophones stretch back millennia to instruments like the Persian oud and Roman cithara. However, early renaissance instruments differed radically from modern guitars. For one thing, strings were manufactured entirely from animal gut, which provided a gentle, mellow timbre but lacked volume and was notoriously sensitive to atmospheric humidity.\nTo enable musicians to stop the vibrating string accurately at chromatic pitch intervals, luthiers developed the wooden fretboard, initially embedding tied gut frets before transitioning to permanent metal wire frets.\nBecause unamplified vibrating strings produce very little audible disturbance in the air on their own, the primary function of the hollow wooden soundbox is acoustic amplification. The thin spruce soundboard vibrates in sympathetically driven cycles, transferring string kinetic energy through the bridge to pump air within the chamber.\nAs performance venues grew from aristocratic drawing rooms to large public concert halls, musicians demanded greater sonic projection. In the mid-19th century, gut strings were replaced by wire strings. However, these steel strings imposed immense mechanical tension on the wooden frame, requiring internal structural reinforcement.\nTo withstand this stress while maintaining tonal warmth, luthiers perfected the iconic figure-eight curved body design. The narrow waist allowed the instrument to sit comfortably on the performer's thigh while increasing structural rigidity.\nThe greatest breakthrough occurred in 19th-century Spain, where Antonio de Torres pioneered the fan-bracing pattern inside the soundboard, creating what is recognized today as the modern classical guitar.\nIn the 1930s, big-band musicians struggled to compete with loud horn sections. This dilemma spurred the development of magnetic pickups placed directly beneath metal strings. These electromagnetic transducers converted string vibrations into electrical currents.\nYet early hollow-body electric guitars suffered from severe acoustic feedback howl when plugged into high-power amplifiers. To eradicate this acoustic interference, inventors developed the solid body electric guitar, famously exemplified by the Fender Broadcaster and Gibson Les Paul.\nIn recent decades, aeronautical materials have influenced lutherie. Modern guitars often incorporate carbon-fibre composite materials to ensure sustained resonance and structural immunity to changes in humidity.\nUltimately, these engineering innovations did more than alter an instrument; they transformed the 20th-century recording studio and gave birth to modern popular music genres worldwide.",
