        "transcript": "MANAGER: Welcome to Harbour FM 104, your independent non-profit community radio station. Since our founding twelve years ago, we have broadcast 24/7 across the maritime district.\nUnlike commercial broadcasters reliant on advertising, our core operations are funded by municipal cultural grants and individual listener subscriptions.\nFor our volunteer training program, no prior broadcast experience is required. We offer a four-week comprehensive course covering vocal delivery, interviewing techniques, and sound mixing.\nVolunteers who complete the introductory course commit to producing a two-hour weekly community interest show.\nAll broadcast team members must uphold strict media regulatory standards; defamation or unauthorized copyrighted music playback will result in immediate suspension.\nNow, let me give you an overview of our broadcasting suite layout. Coming through the main reception lobby, located at the front of the building, the glass door directly ahead takes you into the Master On-Air Studio at Location B. Off to your left, soundproofed with acoustic foam tiles, is the Audio Editing Suite at Location D. If you proceed past the on-air booth down the central corridor, the Newsroom and wire terminal room is at Location A. Across from the newsroom, situated at Location E, is the Music Archive room containing our digitized library of over fifty thousand tracks. The Green Room where guest interviewees wait before going live is located at Location C, equipped with tea and coffee facilities. Finally, the station Technical Server and transmission hub is located securely at the back at Location F. Let us head into the on-air booth for a live demonstration!",
