        "part": 2,
        "title": "Science & Discovery Museum Redevelopment Tour",
        "instructions": "Answer Questions 11 to 20 based on the talk given by the museum education curator.",
        "transcript": "CURATOR: Good afternoon, members and patrons. Welcome to our preview tour of the newly modernized City Science and Discovery Museum.\nOur six-month redevelopment focused heavily on inclusive learning. Over forty percent of our exhibits now feature tactile interactive stations with braille labels and multi-sensory sound effects.\nOur star addition is the state-of-the-art digital planetarium dome, presenting immersive 360-degree cosmological journeys.\nFor school bookings, we are introducing a generous educational policy: all state-funded primary schools receive free weekday admission for pupils and teachers.\nTo avoid congestion, we have implemented timed entry passes reserved through our online ticketing portal.\nLet us consult the new gallery layout map. Standing here at the Main Ticketing Atrium, directly ahead through the archway at Location C is the Earth & Geology Hall. To your immediate left at Location A is the Robotics Arena, where visitors can program autonomous rovers. Next to robotics along the western wall at Location D is the Hands-On Physics Lab. Opposite the physics lab on the east side at Location B is the Planetarium Dome. Directly behind the geology hall at Location E is the Prehistoric Fossil Pavilion, featuring our iconic reconstructed Tyrannosaurus skeleton. Finally, the Museum Cafe and terrace overlooking the public gardens is located at Location F. Let us begin our walk in the robotics gallery!",
