        "instructions": "Complete the notes below. Write NO MORE THAN TWO WORDS for each answer.",
        "transcript": "LECTURER: In today's economic history lecture, we examine sericulture—the ancient cultivation and manufacture of natural silk.\nAccording to Chinese archaeological evidence, silk production originated in the Neolithic Yangshao culture over five thousand years ago. Legend attributes the discovery to Empress Leizu, who allegedly noticed a cocoon unraveling in her steaming cup of tea.\nThe biological source of luxury silk is the domesticated silkmoth caterpillar, Bombyx mori. These delicate insects feed exclusively on the leaves of the white mulberry tree.\nAfter several instars, the mature silkworm spins an intact protective cocoon, secreting a continuous proteinaceous filament up to one kilometre in length from its salivary spinnerets.\nThe silk thread consists of strong inner fibroin proteins held together by a gummy coating called sericin. To harvest the thread without breaking it, cocoons are immersed in boiling water. The heat dissolves the sticky sericin, enabling workers to locate the filament end and reel it onto spools.\nFor centuries, the Chinese imperial court guarded sericulture secrets under penalty of execution. Smuggling silkworm eggs or mulberry seeds abroad was deemed high treason.\nSilk possessed extraordinary commercial value: it was accepted as standard currency for tax payments, military salaries, and foreign tribute throughout imperial dynasties.\nThe fabric's distinctive shimmering lustre is caused by the triangular cross-section of fibroin filaments, which acts like optical prisms, refracting light at diverse angles.\nMechanically, natural silk possesses astonishing tensile strength, exceeding that of high-tensile steel wire of equivalent diameter.\nIn modern biotechnology, natural silk fibroin is engineered into biocompatible surgical sutures, artificial ligaments, and biodegradable micro-capsules for targeted drug delivery.",
