        "transcript": "CLARA: Good morning. I saw an advertisement on the community board about volunteering for the Preston Park Run. Is this the right department?\nCOORDINATOR: Yes, absolutely! We are always delighted to welcome new volunteers. Let me take down a few details so we can get you registered.\nCLARA: Wonderful. Where do all the volunteers meet on the day of the event?\nCOORDINATOR: Everyone gathers outside the cafe situated right near the south entrance of the park. That is where we distribute high-visibility vests.\nCLARA: Outside the cafe, noted. And what time do the races actually commence?\nCOORDINATOR: The briefing for marshals is earlier, but the runners start at 9 am sharp every Saturday.\nCLARA: 9 am, perfect. What is the total route distance?\nCOORDINATOR: It is a standard 5km course that loops twice through the meadow and woodland paths.\nCLARA: 5km sounds great. Do participants need to bring any registration document?\nCOORDINATOR: Yes, every participant must bring a printed barcode. Without that, our electronic scanners cannot register their finishing time.\nCLARA: Right, their barcode. Where do they check the weekly results afterwards?\nCOORDINATOR: All weekly timings are uploaded directly to our official website by Saturday afternoon.\nCLARA: Excellent. Is there a fee for parking in the park's designated visitor lot?\nCOORDINATOR: Parking costs 1.50 for the entire morning, payable at the ticket machine.\nCLARA: Just 1.50, that is very reasonable. Could you give me the coordinator's surname for reference?\nCOORDINATOR: Yes, my surname is Maughan. That is spelt M - A - U - G - H - A - N.\nCLARA: M - A - U - G - H - A - N. And your direct office telephone number?\nCOORDINATOR: It is 01444732900.\nCLARA: 01444732900. Fantastic. Which specific volunteer roles are currently available?\nCOORDINATOR: We particularly need guide runners to accompany visually impaired athletes along the route.\nCLARA: That sounds very rewarding. Is there any other role?\nCOORDINATOR: We also need someone responsible for taking photographs near the finish line for our community newsletter.\nCLARA: Splendid! I love photography, so taking photographs would be ideal.",
