        "title": "Marine Biology Fieldwork - Coastal Reefs & Fish Populations",
        "instructions": "Answer Questions 21 to 30 based on the discussion between two undergraduate students and their tutor.",
        "transcript": "TUTOR: Good afternoon Sophie, Tom. Let's look over your progress on the Sandy Bay coastal marine survey. Why did you choose Sandy Bay over North Cove?\nSOPHIE: Well, North Cove is popular with tourists, but Sandy Bay offers a much greater variety of marine habitats—we had rocky outcrops, shallow seagrass beds, and tidal estuaries all within walking distance.\nTOM: That made comparative species sampling much easier.\nTUTOR: Excellent choice. What proved to be the most challenging aspect of your fieldwork?\nTOM: Collecting the water samples at low tide. We hadn't anticipated the exceptionally strong tidal currents sweeping around the headland; we almost lost our sampling canister.\nSOPHIE: And when analyzing our salinity readings back in the lab, we noticed an anomaly between Tuesday and Thursday.\nTUTOR: What caused that discrepancy?\nSOPHIE: It turned out to be a faulty sensor calibration on our digital probe, not an actual shift in freshwater runoff.\nTOM: Once we recalibrated against a standard solution, the data aligned smoothly.\nTUTOR: Did you observe any unexpected fish behavior in the reef zone?\nTOM: Yes! We expected the juvenile fish to disperse into open water during high tide, but they remained tightly sheltering among the submerged seagrass roots to evade predators.\nTUTOR: Very interesting observation. Where did you source your historical fish population statistics?\nSOPHIE: Initially we looked at local angling records, but they were unreliable. Ultimately we extracted ten years of certified catch data from the university database archives.\nTUTOR: That gives your paper far more academic credibility. Now, looking at your first report draft, the introductory literature review is thorough, but you need to incorporate more comparative charts to highlight the seasonal variance.\nTOM: We can certainly generate those from our spreadsheet.\nTUTOR: Right, let's agree on the delegation for the final deliverables.\nSOPHIE: I am happy to carry out the statistical correlation modeling for our salinity and species count figures.\nTOM: And I will take responsibility for reviewing and transcribing the underwater video footage we recorded.\nSOPHIE: I can also write up the section discussing the sea temperature anomalies.\nTOM: And both of us will collaborate on designing the presentation slides for the departmental conference next Friday.\nTUTOR: Perfect. Keep up the high standard of work.",
