        "part": 4,
        "title": "Wildlife Conservation: The Tasmanian Devil & Immune Adaptation",
        "instructions": "Complete the notes below. Write NO MORE THAN TWO WORDS for each answer.",
        "transcript": "LECTURER: Today we focus on an extraordinary conservation battle: the Tasmanian devil, Sarcophilus harrisii, the world's largest surviving carnivorous marsupial.\nEndemic to the island state of Tasmania, devils fill a crucial ecological niche as apex scavengers. Their formidable jaw muscles generate bite forces equivalent to a dog four times their weight, allowing them to crush and consume bone and carcases, thereby cleansing landscapes of disease vectors.\nTragically, since the mid-1990s, the species has suffered catastrophic population declines exceeding eighty percent due to Devil Facial Tumour Disease, or DFTD.\nDFTD is unique: it is one of only three known transmissible cancers in nature. The infectious cancer cells are transferred directly between individuals during social face biting that occurs during mating rituals and territorial disputes.\nNormally, a mammal's immune system detects foreign tissue graft antigens and destroys them. However, due to historic demographic bottlenecks and island isolation, Tasmanian devils exhibit remarkably low genetic diversity, particularly within their major histocompatibility complex genes.\nAs a consequence, the devil's immune system fails to recognize the invading allograft tumour cells as foreign, allowing tumours to metastasize rapidly, causing fatal starvation within months.\nTo prevent extinction, conservationists established insurance populations on predator-free offshore islands, such as Maria Island, preserving disease-free genetic reserves.\nMore recently, evolutionary biologists have documented rapid genomic adaptation in wild populations. Genomic sequencing reveals specific gene loci associated with immune regulation undergoing intense natural selection.\nA small percentage of wild individuals have developed natural antibodies capable of suppressing tumour growth, exhibiting spontaneous regression.\nBy combining captive breeding, genetic mapping, and monitored reintroductions to mainland sanctuaries, scientists are hopeful this iconic marsupial will survive and restore balanced trophic ecosystems.",
