        "instructions": "Answer Questions 11 to 20 based on the talk given by the urban transport coordinator.",
        "transcript": "COORDINATOR: Good morning, commuters. Today I am delighted to introduce our newly expanded CityBike bicycle-sharing network across the metropolitan district.\nTo access the bicycles, riders simply download our mobile smartphone app or tap a contactless credit card at any solar-powered docking kiosk.\nOur pricing model is engineered to encourage short commuter hops: the first 30 minutes of every journey are completely free of charge. Trips exceeding 30 minutes incur a nominal charge of two pounds per half-hour.\nSafety on the road is vital. We encourage all riders to wear helmets, and we have established sanitized helmet dropboxes at five major interchange stations.\nAll CityBike bicycles are equipped with puncture-resistant tires, integrated automatic front and rear dynamo LEDs, and three-speed hub gears.\nNow, let us examine the map of our new city centre docking hubs. Directly opposite Central Railway Station, at Location C, is our largest forty-dock hub. If you travel north toward the financial district, you will find the City Hall docking station at Location A. Situated along the river promenade beside the pedestrian bridge is the Riverfront Esplanade station at Location D. Over in the historic market square, adjacent to the artisan bakeries, is the Old Market hub at Location B. Next to the general hospital entrance is the Medical Centre station at Location E. Finally, serving university students in the cultural precinct, the Arts Campus docking hub is located at Location F. Get on a bike and enjoy green travel!",
