        "part": 4,
        "title": "Infant Language Acquisition and Cognitive Development",
        "instructions": "Complete the notes below. Write NO MORE THAN TWO WORDS for each answer.",
        "transcript": "LECTURER: Today we examine the neurodevelopmental milestones of early language acquisition in human infants.\nFrom the moment of birth, the human auditory cortex displays remarkable sensitivity to human vocalizations. Astonishingly, newborn infants possess universal phoneme discrimination: they can discern subtle acoustic phonetic contrasts across all human languages, whether Hindi retroflex consonants or Japanese liquids.\nHowever, through neural pruning and exposure to the native linguistic environment, this universal capacity narrows by approximately ten months of age, specializing in the sounds of the child's mother tongue.\nCrucial in mediating this developmental trajectory is the infant's exposure to infant-directed speech, colloquially termed parentese. Characterized by higher pitch, exaggerated intonation contours, and elongated vowels, parentese captures infant attention and exaggerates the acoustic boundaries between phonetic syllables.\nAt around six months of age, infants enter the canonical babbling phase, spontaneously producing repetitive consonant-vowel combinations such as 'ba-ba' and 'da-da'. Neuroimaging demonstrates that babbling is not merely vocal motor exercise, but active linguistic neural wiring.\nBy approximately eighteen months, infants experience a rapid lexical explosion, acquiring new words at an astonishing rate of up to nine new vocabulary items per day.\nUnderpinning this cognitive leap is the emergence of joint attention, where infant and caregiver coordinate their gaze toward a shared physical object while vocalizing.\nFurthermore, the activation of frontoparietal mirror neurons allows infants to map observed lip movements and articulatory gestures directly onto their own motor speech cortex.\nIn summary, language acquisition is not a passive sponge-like absorption, but an active, socially guided neurobiological construction.",
