        "instructions": "Complete the notes below. Write NO MORE THAN TWO WORDS for each answer.",
        "transcript": "LECTURER: In today's geology and energy engineering lecture, we examine geothermal power generation.\nDeep beneath the Earth's crust, radioactive decay of potassium, thorium, and uranium generates intense subterranean heat. In geologically active zones—particularly along tectonic plate boundaries known as the Pacific Ring of Fire—magma chambers heat underground groundwater aquifers to temperatures exceeding three hundred degrees Celsius.\nTo harness this thermal energy, engineers drill production wells reaching depths of up to three to four kilometres. The superheated water is brought to the surface under extreme hydrostatic pressure.\nIn flash steam power plants, as the high-pressure liquid ascends into low-pressure surface separator vessels, it instantaneously vaporizes into dry steam. This expanding steam drives high-velocity turbine rotors, which spin electromagnetic generators to produce electricity.\nWhere geothermal reservoirs contain moderate-temperature brine below two hundred degrees, engineers deploy binary cycle technology. The geothermal water passes through a heat exchanger, transferring thermal energy to a secondary working fluid with a much lower boiling point, such as isobutane.\nThe vaporized hydrocarbon fluid turns the turbine before being condensed back into liquid inside a closed loop, releasing zero atmospheric emissions.\nUnlike solar and wind energy which are inherently intermittent, geothermal power provides continuous baseload electricity twenty-four hours a day, unaffected by weather conditions.\nCrucially, to prevent depletion and avoid ground subsidence, the cooled geothermal fluid is injected back into the reservoir via deep reinjection wells.\nIn countries like Iceland, geothermal energy fulfills over ninety percent of domestic space heating and thirty percent of national electrical demand, serving as a global blueprint for sustainable decarbonization.",
